    if (e.target.tagName === "INPUT") return;
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "z") { e.preventDefault(); e.shiftKey ? step(redo, undo) : step(undo, redo); return; }
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "s") { e.preventDefault(); save(title.value); return; }
    const t = { b: "brush", p: "pencil", h: "marker", s: "spray", e: "eraser", g: "fill", l: "line", r: "rect", o: "ellipse", i: "pick" }[e.key.toLowerCase()];
    if (t) setTool(t);
    if (e.key === "[") size = Math.max(1, size - 2), root.querySelector(".size").value = size;
    if (e.key === "]") size = Math.min(120, size + 2), root.querySelector(".size").value = size;
